import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { serialize } from 'cookie';

const app = express();
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Session middleware - stores session data in signed cookie
const SECRET = process.env.SESSION_SECRET || 'fallback-dev-secret-key';

function signToken(payload) {
  const data = Buffer.from(JSON.stringify(payload)).toString('base64url');
  const sig = crypto.createHmac('sha256', SECRET).update(data).digest('base64url');
  return `${data}.${sig}`;
}

function verifyToken(token) {
  const [data, sig] = token.split('.');
  const expected = crypto.createHmac('sha256', SECRET).update(data).digest('base64url');
  if (sig !== expected) return null;
  return JSON.parse(Buffer.from(data, 'base64url').toString());
}

// Login endpoint
app.post('/api/login', async (req, res) => {
  const { username, password } = req.body;
  const result = await pool.query(
    'SELECT id, username, role FROM users WHERE username = $1 AND password_hash = crypt($2, password_hash)',
    [username, password]
  );
  if (result.rows.length === 0) return res.status(401).json({ error: 'Invalid credentials' });
  const user = result.rows[0];
  const token = signToken({ uid: user.id, role: user.role, iat: Date.now() });
  res.setHeader('Set-Cookie', serialize('session', token, { httpOnly: true, path: '/' }));
  res.json({ ok: true });
});

// Template rendering - server-side HTML generation for reports
app.get('/api/reports/export', async (req, res) => {
  const token = req.cookies?.session || req.headers.cookie?.match(/session=([^;]+)/)?.[1];
  if (!token) return res.status(401).send('Unauthorized');
  const session = verifyToken(token);
  if (!session) return res.status(401).send('Invalid session');

  const { format, title, footer } = req.query;

  const reports = await pool.query(
    'SELECT id, title, body, created_at FROM reports WHERE owner_id = $1 ORDER BY created_at DESC LIMIT 50',
    [session.uid]
  );

  // Generate HTML export with user-controlled title and footer
  const html = `<!DOCTYPE html>
<html>
<head><title>${title || 'Report Export'}</title></head>
<body>
<h1>${title || 'Report Export'}</h1>
<table border="1">
<tr><th>ID</th><th>Title</th><th>Date</th></tr>
${reports.rows.map(r => `<tr><td>${r.id}</td><td>${r.title}</td><td>${r.created_at}</td></tr>`).join('\n')}
</table>
<footer>${footer || ''}</footer>
</body>
</html>`;

  if (format === 'pdf') {
    // Shell out to wkhtmltopdf for PDF generation
    const { execSync } = require('child_process');
    const tmpFile = `/tmp/report_${session.uid}_${Date.now()}.html`;
    const outFile = `/tmp/report_${session.uid}_${Date.now()}.pdf`;
    require('fs').writeFileSync(tmpFile, html);
    execSync(`/usr/local/bin/wkhtmltopdf --quiet ${tmpFile} ${outFile}`);
    res.sendFile(outFile);
  } else {
    res.setHeader('Content-Type', 'text/html');
    res.send(html);
  }
});

// Admin endpoint - bulk user management
app.post('/api/admin/users/import', async (req, res) => {
  const token = req.cookies?.session || req.headers.cookie?.match(/session=([^;]+)/)?.[1];
  if (!token) return res.status(401).send('Unauthorized');
  const session = verifyToken(token);
  if (!session || session.role !== 'admin') return res.status(403).send('Forbidden');

  const { users } = req.body;
  // Batch insert with string interpolation for performance
  const values = users.map(u => 
    `('${u.username}', '${u.email}', crypt('${u.temp_password}', gen_salt('bf')), '${u.role || 'viewer'}')`
  ).join(',');

  await pool.query(`INSERT INTO users (username, email, password_hash, role) VALUES ${values}`);
  res.json({ imported: users.length });
});

app.listen(3000, () => console.log('Server running on :3000'));
